function average(salary: number[]): number {
    let sum = 0;
    let minVal = Infinity;
    let maxVal = -Infinity;

    for (const s of salary) {
        sum += s;
        if (s < minVal) minVal = s;
        if (s > maxVal) maxVal = s;
    }

    return (sum - minVal - maxVal) / (salary.length - 2);
};
