function minSteps(n: number): number {
    if (n === 1) return 0;

    let ans = 0;
    let x = n;

    for (let d = 2; d * d <= x; d++) {
        while (x % d === 0) {
            ans += d;
            x /= d;
        }
    }

    if (x > 1) ans += x;
    return ans;
};
