function ambiguousCoordinates(s: string): string[] {
    const digits = s.slice(1, -1);
    const n = digits.length;
    const res: string[] = [];

    function makeNums(str: string): string[] {
        const ans: string[] = [];
        if (str.length === 1) {
            ans.push(str);
            return ans;
        }

        // Integer form
        if (str[0] !== '0') ans.push(str);

        // Decimal forms
        for (let i = 1; i < str.length; i++) {
            const left = str.slice(0, i);
            const right = str.slice(i);

            // Leading zero allowed only as "0.xxx"
            if (left.length > 1 && left[0] === '0') continue;
            // Trailing zero not allowed in decimal part
            if (right[right.length - 1] === '0') continue;

            ans.push(left + '.' + right);
        }

        return ans;
    }

    for (let i = 1; i < n; i++) {
        const leftPart = digits.slice(0, i);
        const rightPart = digits.slice(i);

        const leftNums = makeNums(leftPart);
        const rightNums = makeNums(rightPart);

        for (const a of leftNums) {
            for (const b of rightNums) {
                res.push(`(${a}, ${b})`);
            }
        }
    }

    return res;
};

