function numFactoredBinaryTrees(arr: number[]): number {
    const MOD = 1000000007;
    arr.sort((a, b) => a - b);
    const n = arr.length;
    const dp = new Array<number>(n).fill(1);
    const indexMap = new Map<number, number>();
    for (let i = 0; i < n; i++) indexMap.set(arr[i], i);

    for (let i = 0; i < n; i++) {
        const x = arr[i];
        for (let j = 0; j < i; j++) {
            const a = arr[j];
            if (x % a !== 0) continue;
            const b = x / a;
            const k = indexMap.get(b);
            if (k === undefined) continue;
            dp[i] = (dp[i] + (dp[j] * dp[k]) % MOD) % MOD;
        }
    }

    let ans = 0;
    for (const v of dp) ans = (ans + v) % MOD;
    return ans;
};
```

