class MKAverage {
    private m: number;
    private k: number;
    private q: number[] = [];
    private cnt: number[] = Array(100001).fill(0);
    private leftSize: number = 0;
    private midSize: number = 0;
    private rightSize: number = 0;
    private leftSum: number = 0;
    private midSum: number = 0;
    private rightSum: number = 0;

    constructor(m: number, k: number) {
        this.m = m;
        this.k = k;
    }

    addElement(num: number): void {
        this.q.push(num);
        if (this.q.length <= this.m) {
            this.insert(num);
            if (this.q.length === this.m) {
                this.rebalanceAll();
            }
        } else {
            const old = this.q[this.q.length - this.m - 1];
            this.remove(old);
            this.insert(num);
            this.rebalanceAll();
        }
    }

    calculateMKAverage(): number {
        if (this.q.length < this.m) return -1;
        return Math.floor(this.midSum / (this.m - 2 * this.k));
    }

    private insert(x: number): void {
        this.cnt[x]++;
    }

    private remove(x: number): void {
        this.cnt[x]--;
    }

    private rebalanceAll(): void {
        this.leftSize = this.midSize = this.rightSize = 0;
        this.leftSum = this.midSum = this.rightSum = 0;

        let needLeft = this.k;
        let needMid = this.m - 2 * this.k;
        let needRight = this.k;

        for (let v = 1; v <= 100000; v++) {
            let c = this.cnt[v];
            if (c === 0) continue;

            let take = Math.min(c, needLeft);
            this.leftSize += take;
            this.leftSum += take * v;
            c -= take;
            needLeft -= take;
            if (c === 0) continue;

            take = Math.min(c, needMid);
            this.midSize += take;
            this.midSum += take * v;
            c -= take;
            needMid -= take;
            if (c === 0) continue;

            take = Math.min(c, needRight);
            this.rightSize += take;
            this.rightSum += take * v;
            c -= take;
            needRight -= take;
        }
    }
}

