function canCross(stones: number[]): boolean {
    const n = stones.length;
    if (n < 2 || stones[1] !== 1) return false;

    const indexMap = new Map<number, number>();
    for (let i = 0; i < n; i++) indexMap.set(stones[i], i);

    const dp: Set<number>[] = Array.from({ length: n }, () => new Set<number>());
    dp[0].add(0);

    for (let i = 0; i < n; i++) {
        for (const k of dp[i]) {
            for (let next = k - 1; next <= k + 1; next++) {
                if (next <= 0) continue;
                const pos = stones[i] + next;
                const j = indexMap.get(pos);
                if (j !== undefined) {
                    dp[j].add(next);
                    if (j === n - 1) return true;
                }
            }
        }
    }

    return dp[n - 1].size > 0;
};
