function maxPoints(points: number[][]): number {
    const n = points.length;
    if (n <= 2) return n;

    let ans = 2;

    const gcd = (a: number, b: number): number => {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    for (let i = 0; i < n; i++) {
        const map = new Map<string, number>();
        let localMax = 0;

        for (let j = i + 1; j < n; j++) {
            let dx = points[j][0] - points[i][0];
            let dy = points[j][1] - points[i][1];

            const g = gcd(dx, dy);
            dx /= g;
            dy /= g;

            // normalize sign so each slope has a unique representation
            if (dx < 0) {
                dx = -dx;
                dy = -dy;
            } else if (dx === 0) {
                dy = 1;
            } else if (dy === 0) {
                dx = 1;
            }

            const key = dx + "," + dy;
            const count = (map.get(key) || 0) + 1;
            map.set(key, count);
            if (count > localMax) localMax = count;
        }

        ans = Math.max(ans, localMax + 1);
    }

    return ans;
};
