function isCousins(root: TreeNode | null, x: number, y: number): boolean {
    if (!root) return false;

    let parentX: TreeNode | null = null;
    let parentY: TreeNode | null = null;
    let depthX = -1;
    let depthY = -1;

    const queue: Array<[TreeNode, TreeNode | null, number]> = [[root, null, 0]];
    let head = 0;

    while (head < queue.length && (depthX === -1 || depthY === -1)) {
        const [node, parent, depth] = queue[head++];

        if (node.val === x) {
            parentX = parent;
            depthX = depth;
        } else if (node.val === y) {
            parentY = parent;
            depthY = depth;
