function maxRunTime(n: number, batteries: number[]): number {
    batteries.sort((a, b) => a - b);

    let total = 0n;
    for (const b of batteries) total += BigInt(b);

    let left = 0;
    let right = Math.floor(Number(total / BigInt(n)));

    const can = (t: number): boolean => {
        let sum = 0n;
        const T = BigInt(t);
        for (const b of batteries) {
            sum += BigInt(Math.min(b, t));
        }
        return sum >= T * BigInt(n);
    };

    while (left < right) {
        const mid = Math.floor((left + right + 1) / 2);
        if (can(mid)) left = mid;
        else right = mid - 1;
    }

    return left;
};
