    const m = grid.length;
    const n = grid[0].length;

    const rowPref: number[][] = Array.from({ length: m }, () => Array(n + 1).fill(0));
    const colPref: number[][] = Array.from({ length: m + 1 }, () => Array(n).fill(0));

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            rowPref[i][j + 1] = rowPref[i][j] + grid[i][j];
            colPref[i + 1][j] = colPref[i][j] + grid[i][j];
        }
    }

    const rowSum = (r: number, c1: number, c2: number): number => rowPref[r][c2 + 1] - rowPref[r][c1];
    const colSum = (c: number, r1: number, r2: number): number => colPref[r2 + 1][c] - colPref[r1][c];

    const maxK = Math.min(m, n);

    for (let k = maxK; k >= 1; k--) {
        for (let r = 0; r + k - 1 < m; r++) {
            for (let c = 0; c + k - 1 < n; c++) {
                const target = rowSum(r, c, c + k - 1);

                let ok = true;

                for (let i = 1; i < k; i++) {
                    if (rowSum(r + i, c, c + k - 1) !== target) {
                        ok = false;
                        break;
