function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;

    const validMasks: number[] = [];
    const countBits = (x: number): number => {
        let c = 0;
        while (x) {
            x &= x - 1;
            c++;
        }
        return c;
    };

    for (let mask = 0; mask < (1 << n); mask++) {
        let ok = true;
        for (let j = 0; j < n; j++) {
            if ((mask & (1 << j)) === 0) continue;
            if (seats[0][j] === '#') {
                ok = false;
                break;
            }
        }
        if (ok) validMasks.push(mask);
    }

    const rowMasks: number[][] = Array.from({ length: m }, () => []);
    for (let i = 0; i < m; i++) {
        for (let mask = 0; mask < (1 << n); mask++) {
            let ok = true;
            for (let j = 0; j < n; j++) {
                if ((mask & (1 << j)) !== 0 && seats[i][j] === '#') {
                    ok = false;
                    break;
                }
            }
            if (ok && (mask & (mask << 1)) === 0) rowMasks[i].push(mask);
        }
    }

    const dpPrev = new Map<number, number>();
    dpPrev.set(0, 0);

    for (let i = 0; i < m; i++) {
        const dpCurr = new Map<number, number>();
        for (const mask of rowMasks[i]) {
            const bits = countBits(mask);
            for (const [pmask, val] of dpPrev.entries()) {
                if ((mask & (pmask << 1)) !== 0) continue;
                if ((mask & (pmask >> 1)) !== 0) continue;
                const nv = val + bits;
                const old = dpCurr.get(mask);
                if (old === undefined || nv > old) dpCurr.set(mask, nv);
            }
        }
        dpPrev.clear();
        for (const [k, v] of dpCurr.entries()) dpPrev.set(k, v);
    }

    let ans = 0;
    for (const v of dpPrev.values()) ans = Math.max(ans, v);
    return ans;
};

