function maxSumTwoNoOverlap(nums: number[], firstLen: number, secondLen: number): number {
    const n = nums.length;
    const pre = new Array<number>(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];

    function sum(l: number, r: number): number {
        return pre[r] - pre[l];
    }

    function solve(L: number, R: number): number {
        let bestL = sum(0, L);
        let ans = 0;
        for (let i = L + R; i <= n; i++) {
            bestL = Math.max(bestL, sum(i - R - L, i - R));
            ans = Math.max(ans, bestL + sum(i - R, i));
        }
        return ans;
    }

    return Math.max(solve(firstLen, secondLen), solve(secondLen, firstLen));
};

