function minSessions(tasks: number[], sessionTime: number): number {
    const n = tasks.length;
    const m = 1 << n;
    const sum = new Array<number>(m).fill(0);

    for (let mask = 1; mask < m; mask++) {
        const lsb = mask & -mask;
        const idx = Math.floor(Math.log2(lsb));
        sum[mask] = sum[mask ^ lsb] + tasks[idx];
    }

    const dp = new Array<number>(m).fill(n + 1);
    dp[0] = 0;

    for (let mask = 1; mask < m; mask++) {
        let sub = mask;
        while (sub > 0) {
            if (sum[sub] <= sessionTime) {
                dp[mask] = Math.min(dp[mask], dp[mask ^ sub] + 1);
            }
            sub = (sub - 1) & mask;
        }
    }

    return dp[m - 1];
};
