function nextGreaterElements(nums: number[]): number[] {
    const n = nums.length;
    const res = new Array<number>(n).fill(-1);
    const stack: number[] = []; // indices, maintaining decreasing values

    for (let i = 0; i < 2 * n; i++) {
        const cur = nums[i % n];
        while (stack.length > 0 && nums[stack[stack.length - 1]] < cur) {
            const idx = stack.pop()!;
            res[idx] = cur;
        }
        if (i < n) stack.push(i);
    }

    return res;
};
