function nextBeautifulNumber(n: number): number {
    const nums: number[] = [];

    const digits = [1, 2, 3, 4, 5, 6, 7];
    const used = new Array(8).fill(0);

    function permute(arr: number[], l: number) {
        if (l === arr.length) {
            const val = Number(arr.join(""));
            nums.push(val);
            return;
        }
        for (let i = l; i < arr.length; i++) {
            if (i !== l && arr[i] === arr[l]) continue;
            [arr[l], arr[i]] = [arr[i], arr[l]];
            permute(arr, l + 1);
            [arr[l], arr[i]] = [arr[i], arr[l]];
        }
    }

    function dfs(idx: number, len: number) {
        if (idx === digits.length) {
            const arr: number[] = [];
            for (let d = 1; d <= 7; d++) {
                for (let c = 0; c < used[d]; c++) arr.push(d);
            }
            if (arr.length > 0) permute(arr, 0);
            return;
        }

        const d = digits[idx];
        used[d] = 0;
        dfs(idx + 1, len);
        if (len + d <= 7) {
            used[d] = d;
            dfs(idx + 1, len + d);
        }
        used[d] = 0;
    }

    dfs(0, 0);
    nums.sort((a, b) => a - b);

    for (const x of nums) {
        if (x > n) return x;
    }
    return -1;
}
