function numTriplets(nums1: number[], nums2: number[]): number {
    function countTriplets(a: number[], b: number[]): number {
        const freq = new Map<number, number>();
        for (const x of b) freq.set(x, (freq.get(x) || 0) + 1);

        let ans = 0;

        for (const x of a) {
            const target = x * x;
            for (const [v, c] of freq.entries()) {
                if (target % v !== 0) continue;
                const u = target / v;
                if (!freq.has(u)) continue;

                if (u === v) {
                    ans += (c * (c - 1)) / 2;
                } else if (u > v) {
                    ans += c * (freq.get(u)!);
                }
            }
        }
        return ans;
    }

    return countTriplets(nums1, nums2) + countTriplets(nums2, nums1);
};

