function medianSlidingWindow(nums: number[], k: number): number[] {
    class DualHeap {
        small: MaxHeap;
        large: MinHeap;
        delayed: Map<number, number>;
        smallSize: number = 0;
        largeSize: number = 0;

        constructor(private k: number) {
            this.small = new MaxHeap();
            this.large = new MinHeap();
            this.delayed = new Map();
        }

        prune(heap: MaxHeap | MinHeap): void {
            while (heap.size() > 0) {
                const num = heap.peek()!;
                const count = this.delayed.get(num);
                if (count === undefined) break;
                if (count === 1) this.delayed.delete(num);
                else this.delayed.set(num, count - 1);
                heap.pop();
            }
        }

        makeBalance(): void {
            if (this.smallSize > this.largeSize + 1) {
                this.large.push(this.small.pop()!);
                this.smallSize--;
                this.largeSize++;
                this.prune(this.small);
            } else if (this.smallSize < this.largeSize) {
                this.small.push(this.large.pop()!);
                this.smallSize++;
                this.largeSize--;
                this.prune(this.large);
            }
        }

        insert(num: number): void {
            if (this.small.size() === 0 || num <= this.small.peek()!) {
                this.small.push(num);
                this.smallSize++;
            } else {
                this.large.push(num);
                this.largeSize++;
            }
            this.makeBalance();
        }

        erase(num: number): void {
            this.delayed.set(num, (this.delayed.get(num) || 0) + 1);
            if (num <= this.small.peek()!) {
                this.smallSize--;
                if (num === this.small.peek()) this.prune(this.small);
            } else {
                this.largeSize--;
                if (this.large.size() > 0 && num === this.large.peek()) this.prune(this.large);
            }
            this.makeBalance();
        }

        getMedian(): number {
            if (this.k % 2 === 1) return this.small.peek()!;
            return (this.small.peek()! + this.large.peek()!) / 2;
        }
    }

    class MaxHeap {
