    if (nums[0] > target) return false;

    const fullMask = (1 << n) - 1;
    const memo = new Map<number, boolean>();

    function dfs(mask: number, currSum: number, formed: number): boolean {
        if (formed === k - 1) return true;
        const key = mask;
        if (currSum === 0 && memo.has(key)) return memo.get(key)!;

        for (let i = 0; i < n; i++) {
