function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const memo = new Map<string, [number, number]>();

    function dfs(total: number, a: number, b: number): [number, number] {
        if (a > b) [a, b] = [b, a];
        const key = `${total},${a},${b}`;
        const cached = memo.get(key);
        if (cached) return cached;

        if (a + b === total + 1) return [1, 1];

        let earliest = Infinity;
        let latest = -Infinity;

        const leftPairs = a - 1;
        const betweenPairs = b - a - 1;
        const rightPairs = total - b;

        const minWinsLeft = 0;
        const maxWinsLeft = leftPairs;
        const minWinsBetween = 0;
        const maxWinsBetween = betweenPairs;
        const minWinsRight = 0;
        const maxWinsRight = rightPairs;

        for (let x = minWinsLeft; x <= maxWinsLeft; x++) {
            for (let y = minWinsBetween; y <= maxWinsBetween; y++) {
                for (let z = minWinsRight; z <= maxWinsRight; z++) {
